/**
 * Exact solver results for the app's presets, for drawing behind the surrogate's prediction.
 *
 * This is the honest way to present an approximation: not a claim about its error in prose, but
 * both curves on one axis where a reader can see the difference. It only covers the presets --
 * running the panel method in the browser would mean porting it, and a free-form section has no
 * reference to compare against anyway. The overlay appears for a stock section and quietly does not
 * for an edited one.
 *
 * Generated by `tools/dataset/make_overlay.py` and fetched lazily; 140 kB that nobody pays for until
 * the chart is on screen.
 */

import { useEffect, useState } from 'react'

export interface OverlayEntry {
  readonly alphaDeg: number
  readonly status: string
  readonly cl: number
  readonly cd: number | null
  readonly cmQuarter: number
  readonly cp: number[]
}

interface OverlayFile {
  readonly alphaStep: number
  readonly cases: Record<string, OverlayEntry[]>
}

export interface SolverOverlay {
  /** The exact result for a preset at an incidence, or null when there is none to show. */
  readonly lookup: (presetId: string | null, alphaDeg: number) => OverlayEntry | null
  readonly loaded: boolean
}

function overlayUrl(): string {
  const base = import.meta.env.BASE_URL
  return `${base.endsWith('/') ? base : `${base}/`}models/solver_overlay.json`
}

export function useSolverOverlay(): SolverOverlay {
  const [file, setFile] = useState<OverlayFile | null>(null)

  useEffect(() => {
    let cancelled = false
    fetch(overlayUrl())
      .then((response) => (response.ok ? (response.json() as Promise<OverlayFile>) : null))
      .then((loaded) => {
        if (!cancelled && loaded) setFile(loaded)
      })
      .catch(() => {
        // The overlay is an enhancement. Its absence must never stop the app working.
      })
    return () => {
      cancelled = true
    }
  }, [])

  return {
    loaded: file !== null,
    lookup: (presetId, alphaDeg) => {
      if (file === null || presetId === null) return null
      const entries = file.cases[presetId]
      if (!entries) return null

      // Nearest sampled angle, but only if it is genuinely near: showing a four-degree result
      // against a two-degree prediction would misrepresent both.
      let best: OverlayEntry | null = null
      let bestDistance = Number.POSITIVE_INFINITY
      for (const entry of entries) {
        const distance = Math.abs(entry.alphaDeg - alphaDeg)
        if (distance < bestDistance) {
          bestDistance = distance
          best = entry
        }
      }
      if (best === null || bestDistance > file.alphaStep / 2 + 1e-6) return null
      return best.status === 'ok' || best.cp.length > 0 ? best : null
    },
  }
}
